import { detectBankingIdentifiers } from "./banking.ts";
import { detectContactDetails } from "./contact.ts";
import { filterDetections, requiresModels } from "./options.ts";
import type { DetectionProgress, WorkerRequest } from "./types.ts";
import { reconcileStructuredValues } from './structured-values.ts';

export function createDetectionEngine() {
  let detector: ReturnType<typeof import("./openmed.ts").loadDetector> | undefined;
  return async ({ text, options, modelRoot }: WorkerRequest, progress: (value: DetectionProgress) => void) => {
    if (!requiresModels(options)) {
      return filterDetections(reconcileStructuredValues(text, [...detectBankingIdentifiers(text), ...detectContactDetails(text)]), options);
    }
    if (!modelRoot) throw new Error("Models required");
    progress({ stage: "loading", completed: 0, total: 0 });
    // Local-only choices never import or initialize the model runtime.
    const { loadDetector } = await import("./openmed.ts");
    detector ??= loadDetector(modelRoot);
    const loaded = await detector;
    return filterDetections(await loaded.detect(text, progress), options);
  };
}

