import { env, pipeline, type TokenClassificationPipeline } from "@huggingface/transformers";
import { decodeBioTokenSpans, type RawTokenClassificationEntity } from "openmed";
import { alignSourceTokens } from "./source-offsets.ts";
import { completeAddressBoundaries } from "./address-boundaries.ts";
import { modelChunkIterator } from "./chunks.ts";
import { mergeModelDetections, modelDetections } from "./model-policy.ts";
import { detectBankingIdentifiers } from "./banking.ts";
import { detectContactDetails } from "./contact.ts";
import type { Detection, DetectionProgress } from "./types.ts";
import manifest from "../../../scripts/model-manifest.json" with { type: "json" };
import { predictAllTokens } from './token-predictions.ts';
import { detectLabelledFields, reconcileLabelledFields } from './labelled-fields.ts';
import { reconcileStructuredValues } from './structured-values.ts';

export interface TokenDetector {
  tokenizer: Pick<TokenClassificationPipeline['tokenizer'], 'encode'>;
  predict(text: string): Promise<RawTokenClassificationEntity[]>;
  dispose(): Promise<unknown>;
}
export type InferenceProvider = (directory: string) => Promise<TokenDetector>;

export async function loadDetector(modelRoot = "/models", wasmPath = "/runtime/", device: "wasm" | "cpu" = "wasm",
  modelDirectories: readonly string[] = manifest.models.map(model => model.directory), provider?: InferenceProvider) {
  // Evaluation may select pinned checkpoints; the app uses the full manifest by default.
  if (!modelDirectories.length || new Set(modelDirectories).size !== modelDirectories.length
    || modelDirectories.some(directory => !manifest.models.some(model => model.directory === directory)))
    throw new Error("Invalid pinned model selection");
  const models = manifest.models.filter(model => modelDirectories.includes(model.directory));
  // All resources must already be installed locally. Never fall back to a Hub or CDN.
  env.allowRemoteModels = false;
  env.allowLocalModels = true;
  env.localModelPath = modelRoot + "/";
  env.useBrowserCache = false;
  env.useFSCache = false;
  env.useWasmCache = false;
  if (env.backends.onnx.wasm) {
    env.backends.onnx.wasm.wasmPaths = {
      // Use the JS loader embedded by Transformers.js with its matching WASM.
      wasm: `${wasmPath}ort-wasm-simd-threaded.asyncify.wasm`,
    };
    env.backends.onnx.wasm.numThreads = 1;
    env.backends.onnx.wasm.proxy = false;
  }
  const classifiers: TokenDetector[] = [];
  try {
    for (const model of models) {
      if (provider) {
        classifiers.push(await provider(model.directory));
        continue;
      }
      const classifier = await pipeline("token-classification", model.directory, {
        device, dtype: "fp32", // The published INT8 graphs have explicit filenames.
        subfolder: "", model_file_name: "model_int8", local_files_only: true,
      });
      classifiers.push({ tokenizer: classifier.tokenizer,
        predict: (text) => predictAllTokens(classifier, text, true),
        dispose: () => classifier.dispose(),
      });
    }
  } catch (error) {
    await Promise.all(classifiers.map((classifier) => classifier.dispose()));
    throw error;
  }
  return {
    async detect(text: string, progress: (value: DetectionProgress) => void): Promise<Detection[]> {
      const plans = [];
      for (const classifier of classifiers) {
        const chunks = [];
        for (const chunk of modelChunkIterator(text, (value) => classifier.tokenizer.encode(value).length)) {
          chunks.push(chunk);
          // Tokenizer planning also allocates temporary data. Yield here as well
          // as during inference, so a large request does not plan in one task.
          await new Promise<void>((resolve) => setTimeout(resolve, 0));
        }
        plans.push({ classifier, chunks });
      }
      const total = plans.reduce((sum, plan) => sum + plan.chunks.length, 0);
      let completed = 0;
      const detections: Detection[] = [];
      for (const [modelIndex, { classifier, chunks }] of plans.entries()) {
        for (const chunk of chunks) {
          // Preserve every prediction, including O and unknown-token source pieces.
          const tokens = await classifier.predict(chunk.text);
          const aligned = alignSourceTokens(chunk.text, tokens);
          const spans = decodeBioTokenSpans(chunk.text, aligned, { threshold: 0 });
          detections.push(...modelDetections(chunk.text, spans).map((span) => ({
            ...span, start: span.start + chunk.start, end: span.end + chunk.start,
            source: `OpenMed · ${models[modelIndex]!.directory === "vietnamese-pii" ? "SuperClinical" : "mSuperClinical"} · INT8`,
          })));
          progress({ stage: "processing", completed: ++completed, total });
          // Let the worker event loop reclaim temporary inference allocations
          // between chunks, even when the WASM promise resolves synchronously.
          await new Promise<void>((resolve) => setTimeout(resolve, 0));
        }
      }
      const fields = detectLabelledFields(text);
      // Keep ambiguous model evidence outside explicit fields: blanket removal of
      // invalid contact guesses can expose credentials misclassified by the model.
      const contextual = mergeModelDetections(detections);
      const completedDetections = completeAddressBoundaries(text, [...contextual, ...fields.detections]);
      return reconcileStructuredValues(text, [...detectBankingIdentifiers(text), ...detectContactDetails(text),
        ...reconcileLabelledFields(text, completedDetections, fields)]);
    },
    dispose: () => Promise.all(classifiers.map((classifier) => classifier.dispose())),
  };
}
